<script lang="ts">
 import{number,stamp,updatedStamp,compact,cost,type Row}from'../lib/api';import{tr}from'../lib/i18n';
 export let settings:Row={};export let quota:Row={};export let summary:Row={};export let preview=false;
 function remaining(w:Row){return number(w?.remaining_percent)??(number(w?.used_percent)===null?null:100-Number(w.used_percent))}
 function quotaColor(n:number|null){return n===null?'#D0D5DD':n>=50?'#7DDEA0':n>=20?'#F6D56B':'#FF8A80'}
 function label(n:number|null){return n===null?'N/A':`${Math.round(n)}%`}
 $: style=settings.visual_style??'classic';$: scope=settings.quota_scope??'auto';
 $: windows=scope==='week'||scope==='auto'&&remaining(quota.primary??{})===null?[['周额度',quota.secondary??{}]]:[['5 小时额度',quota.primary??{}],['周额度',quota.secondary??{}]];
 $: orb=windows[0];$: orbRemaining=remaining(orb?.[1]??{});$: waterY=100-Math.max(10,Math.min(88,orbRemaining??0));
 $: background=settings.background_transparent?`rgba(37,37,42,${Math.max(1/255,(100-Number(settings.background_opacity??70))/100)})`:'rgb(37,37,42)';
 $: status=quota.error??(quota.updated_at?(tr('上次更新：')+updatedStamp(quota.updated_at)):quota.status==='reading'?tr('正在读取'):quota.status==='stale'?tr('数据过期'):'');
</script>
<div class={`floating python-floating ${style}`} class:preview class:docked={!preview&&settings.dock_edge&&settings.dock_edge!=='none'} class:vertical={!preview&&['left','right'].includes(settings.dock_edge)} style:background={style==='orb'&&!settings.dock_edge?'transparent':background} style:border-color={settings.show_border===false?'transparent':settings.border_color??'#8AB4F8'} style="--wails-draggable:drag" draggable="false" ondragstart={event=>event.preventDefault()} role="presentation">
 {#if !preview&&settings.dock_edge&&settings.dock_edge!=='none'}
 {#each windows as [title,w]}{@const n=remaining(w)}<div class="dock-quota"><span>{title==='周额度'?tr('周'):tr('5 小时')}</span><strong style:color={quotaColor(n)}>{label(n)}</strong><div class="meter"><div style:width={`${Math.max(0,Math.min(100,n??0))}%`} style:background={quotaColor(n)}></div></div></div>{/each}
 {:else if style==='orb'}
 <div class="water-orb" title={`${tr(orb[0])} · ${label(orbRemaining)} · ${tr('重置')} ${stamp(orb[1].resets_at)}`}><svg viewBox="0 0 100 100" aria-label={`${tr(orb[0])} ${label(orbRemaining)}`}><defs><clipPath id={preview?'preview-orb-clip':'orb-clip'}><circle cx="50" cy="50" r="48"/></clipPath><radialGradient id={preview?'preview-cavity':'cavity'}><stop offset="0" stop-color="#3A4854"/><stop offset=".7" stop-color="#202A34"/><stop offset="1" stop-color="#141C24"/></radialGradient><linearGradient id={preview?'preview-water':'water'} x1="0" y1="0" x2="0" y2="1"><stop stop-color="#7DF0B5"/><stop offset=".28" stop-color="#3DDC97"/><stop offset="1" stop-color="#1FA97A"/></linearGradient></defs><circle cx="50" cy="50" r="48" fill={`url(#${preview?'preview-cavity':'cavity'})`}/>{#if orbRemaining!==null}<g clip-path={`url(#${preview?'preview-orb-clip':'orb-clip'})`}><path class="orb-water" d={`M-20 ${waterY} Q5 ${waterY-6} 30 ${waterY} T80 ${waterY} T130 ${waterY} V104H-20Z`} fill={`url(#${preview?'preview-water':'water'})`}/></g>{/if}<circle cx="50" cy="50" r="47.5" fill="none" stroke="#E6F0F632" stroke-width="1.3"/><path d="M23 26Q30 14 42 13" fill="none" stroke="#FFFFFF46" stroke-width="1.2"/><text x="50" y="56" text-anchor="middle" font-size="26" fill="#F8FFFC">{label(orbRemaining)}</text></svg>{#if summary.tokens!=null}<small>{compact(summary.tokens)}<br/>{cost(summary.usd)}</small>{/if}</div>
 {:else}
 <div class="floating-quotas">{#each windows as [title,w]}{@const n=remaining(w)}<div class="floating-quota" style={`--quota-color:${quotaColor(n)}`}>
 {#if style==='rings'}<svg viewBox="0 0 100 100"><circle cx="50" cy="50" r="40" fill="none" stroke="#FFFFFF2E" stroke-width="10"/><circle cx="50" cy="50" r="40" fill="none" stroke={quotaColor(n)} stroke-width="10" stroke-linecap="round" pathLength="100" stroke-dasharray={`${Math.max(0,Math.min(100,n??0))} 100`} transform="rotate(-90 50 50)"/><text x="50" y="58" text-anchor="middle" font-size="29" fill="#F0F0F3">{n===null?'N/A':Math.round(n)}</text></svg><span>{tr(title)}</span><small>{stamp(w.resets_at)}</small>
 {:else if style==='classic'}<div class="floating-row-head"><span>{tr(title)}</span><strong>{label(n)}</strong></div><div class="meter"><div style:width={`${Math.max(0,Math.min(100,n??0))}%`}></div></div><small>{tr('重置')} {stamp(w.resets_at)}</small>
 {:else}<strong>{label(n)}</strong><span>{tr(title)}</span>{#if style!=='minimal'}<small>{stamp(w.resets_at)}</small>{/if}{/if}
 </div>{/each}</div>
 {#if !preview&&style!=='minimal'}<div class="floating-status" class:error={!!quota.error}>{status}{#if !quota.error&&summary.tokens!=null}<span>{compact(summary.tokens)} Token {cost(summary.usd)}</span>{/if}</div>{/if}
 {/if}
</div>
<style>
 .python-floating.floating,.python-floating.floating *{user-select:none;-webkit-user-drag:none}.python-floating img{pointer-events:none}
 .python-floating.floating{--text:#F0F0F3;--muted:#AFB0BA;--tokens:#7DDEA0;--raised:#FFFFFF30;--hover:#FFFFFF12;--control:#44444D;color:#F0F0F3;display:flex;flex-direction:column;gap:8px;overflow:hidden;padding:12px 14px;border:1px solid #FFFFFF24;border-radius:18px;backdrop-filter:none;-webkit-backdrop-filter:none;font-family:"Codexio Inter","Microsoft YaHei UI",system-ui,sans-serif;font-size:14px;text-shadow:none;line-height:1.25;box-shadow:0 8px 24px #0005}
 .python-floating.floating.preview{flex-shrink:0;align-self:flex-start;width:320px;max-width:100%;height:160px;min-height:0;padding:16px;--wails-draggable:no-drag!important}.python-floating .floating-brand{font-size:17px;gap:4px;min-height:27px;padding:2px 4px 2px 6px;border-radius:8px;background:#FFFFFF12;flex-shrink:0}.python-floating .floating-brand img{width:18px;height:18px}.python-floating .floating-grip{width:10px;color:#C8CED6;font-size:15px}.python-floating .floating-brand>span:not(.floating-grip),.python-floating .floating-status{text-shadow:0 1px 12px #000000D2}.python-floating .floating-quotas{display:flex;flex:1;min-height:0;gap:12px;margin:0;align-items:stretch;justify-content:space-around}.python-floating.classic .floating-quotas{flex-direction:column}.python-floating .floating-quota{min-height:0;display:flex;flex-direction:column;justify-content:center;gap:4px;flex:1;text-align:center}.python-floating.classic .floating-quota{text-align:left}.python-floating .floating-row-head{display:flex;align-items:center;justify-content:space-between;gap:12px}.python-floating .floating-row-head>span{font-size:14px}.python-floating .floating-quota strong{font-size:32px;color:var(--quota-color);font-weight:400;line-height:1.15}.python-floating.classic .floating-quota strong{font-size:22px}.python-floating .floating-quota>span{font-size:14px;margin:0;color:#E8EAED}.python-floating .floating-quota small{font-size:12px;line-height:1.25;color:#AFB0BA}.python-floating.classic .floating-quota small{font-size:14px}.python-floating .meter{height:8px;flex-shrink:0;margin:0;border-radius:4px;background:#FFFFFF30}.python-floating .meter>div{background:var(--quota-color)}.python-floating .floating-quota svg{height:100%;max-height:120px;width:100%;margin:0 auto;min-height:50px}.python-floating .floating-status{font-size:10px;color:#AFB0BA;display:flex;align-items:center;justify-content:space-between;gap:8px;white-space:nowrap;overflow:hidden;flex-shrink:0;min-height:13px}.python-floating .floating-status>span{font-size:10px}.python-floating.tiles .floating-quota{background:#FFFFFF12;border:1px solid #FFFFFF24;border-radius:14px;padding:8px}.python-floating.compact .floating-quotas{gap:16px}.python-floating.compact .floating-quota strong{font-size:22px}.python-floating.minimal .floating-quotas{gap:0}.python-floating.minimal .floating-quota strong{font-size:32px}.python-floating.minimal .floating-quota>span{font-size:14px}.python-floating.orb{padding:0;border:0;border-radius:0;background:transparent!important;display:grid;place-items:center}.python-floating.orb.preview{width:148px;height:148px}.water-orb{width:min(100%,100vh);height:100%;max-width:100%;aspect-ratio:1;position:relative}.water-orb svg{height:100%;width:100%;display:block}.water-orb small{position:absolute;left:0;right:0;top:64%;text-align:center;font-size:10px;line-height:1.2;color:#F2FFF9}.orb-water{animation:water-wave 3s ease-in-out infinite;transform-origin:center}@keyframes water-wave{0%,100%{transform:translateX(0)}50%{transform:translateX(-10px)}}
 .python-floating.docked{flex-direction:row;padding:7px 12px;gap:14px;border:1px solid #FFFFFF26;border-radius:15px;background-color:#25252A;box-shadow:0 5px 18px #0005}.python-floating.docked .dock-quota{gap:7px}.python-floating.docked .dock-quota>strong{font-size:18px;min-width:42px;font-weight:450}.python-floating.docked .dock-quota>span{color:#D9D9DE;font-size:11px}.python-floating.docked .dock-quota .meter{height:6px}.python-floating.docked.vertical{flex-direction:column;padding:12px 7px;gap:10px;border-radius:17px}.python-floating.docked.vertical .dock-quota>strong{font-size:14px;min-width:0}.python-floating.docked.vertical .dock-quota>span{font-size:9px}.python-floating.docked.vertical .meter{width:34px;height:5px}@media(prefers-reduced-motion:reduce){.orb-water{animation:none}}
</style>
